import{_ as o,o as t,c as a,a1 as i}from"./chunks/framework.Czc1bIXI.js";const u=JSON.parse('{"title":"Rocq development setup","description":"","frontmatter":{},"headers":[],"relativePath":"26-27/setup.md","filePath":"26-27/setup.md"}'),s={name:"26-27/setup.md"};function n(r,e,l,c,d,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="rocq-development-setup" tabindex="-1">Rocq development setup <a class="header-anchor" href="#rocq-development-setup" aria-label="Permalink to &quot;Rocq development setup&quot;">​</a></h1><p>In order to solve the exercises you need to set up <a href="https://rocq-prover.org/" target="_blank" rel="noreferrer">Rocq</a> (preferably in an IDE). For that, you are free to configure your favorite editor, package manager and build tool chain if there exist a Rocq plugin for it. However, by doing so you are on your own.</p><p>If you expect us to help you with this setup, then you should follow our recommendation: Use nix as package manager and VsCode with the VsRocq plugin as editor.</p><h2 id="nix-setup" tabindex="-1">Nix Setup <a class="header-anchor" href="#nix-setup" aria-label="Permalink to &quot;Nix Setup&quot;">​</a></h2><p>To install nix you should follow the official tutorial. (see <a href="https://nixos.org/download/" target="_blank" rel="noreferrer">https://nixos.org/download/</a>)</p><p>Then you should enable the nix flakes feature by writing the following to <code>~/.config/nix/nix.conf</code>:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">experimental-features</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = nix-command flakes</span></span></code></pre></div><p>Just create the file in case it doesn&#39;t exist. (see <a href="https://nixos.wiki/wiki/flakes" target="_blank" rel="noreferrer">https://nixos.wiki/wiki/flakes</a>)</p><h2 id="clone-exercise-repo" tabindex="-1">Clone Exercise Repo <a class="header-anchor" href="#clone-exercise-repo" aria-label="Permalink to &quot;Clone Exercise Repo&quot;">​</a></h2><p>Next you should clone this repository, by calling the following command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://gitlab.barkhauseninstitut.org/versa/teaching/fcplcd-2026</span></span></code></pre></div><p>In case you do not have git installed you can use git through nix by replacing <code>git</code> with <code>nix run nixpkgs#git</code>.</p><p>After you cloned it, go into the repo:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fcplcd-2026</span></span></code></pre></div><h2 id="enter-the-nix-environment" tabindex="-1">Enter the Nix Environment <a class="header-anchor" href="#enter-the-nix-environment" aria-label="Permalink to &quot;Enter the Nix Environment&quot;">​</a></h2><p>Once nix is set up, and you are in the directory of the cloned repository, you simply call <code>nix develop</code> to enter a development shell which will have the necessary binaries available, like <code>coqc</code> or <code>vscoqtop</code>.</p><p>In that environment you need to start VsCode/Codium. It is important that you start it from the shell s.t. it has access to the coq binaries: do not invoke it using your normal program launcher!</p><p>Depending on your installation of VsCode the shell command may differ, I&#39;d assume it is named <code>code</code> or <code>codium</code>. If you pass it a <code>.</code> as first argument it will directly load the current directory as a project, so I recommend calling <code>code .</code> or <code>codium .</code>.</p><h2 id="vsrocq" tabindex="-1">VsRocq <a class="header-anchor" href="#vsrocq" aria-label="Permalink to &quot;VsRocq&quot;">​</a></h2><p>Inside VsCode you then need to install the &#39;VsRocq&#39; extension. (Note: not &#39;VsCoq&#39; and also not &#39;VsCoq Legacy&#39;) After you installed this plugin, everything should work out of the box. You can verify it by going into one of the exercise files and &#39;stepping&#39; through them by using <code>alt</code> + arrow keys <code>→</code> / <code>↑</code> / <code>↓</code>.</p><p>In case you have problems, please reach out via E-Mail to <a href="mailto:fcplcd@barkhauseninstitut.org" target="_blank" rel="noreferrer">fcplcd@barkhauseninstitut.org</a>.</p>',21)])])}const g=o(s,[["render",n]]);export{u as __pageData,g as default};
